let marketingMotionDisposer = null;

function disposeMarketingMotion() {
  if (typeof marketingMotionDisposer === "function") marketingMotionDisposer();
  marketingMotionDisposer = null;
}

function initMarketingMotion() {
  disposeMarketingMotion();
  const root = app.querySelector(".marketing-v3");
  if (!root) return;
  const disposers = [];
  const timers = new Set();
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const observe = (elements, handler, options = { threshold: .16 }) => {
    if (!("IntersectionObserver" in window)) {
      elements.forEach((element) => handler({ target: element, isIntersecting: true }, null));
      return;
    }
    const observer = new IntersectionObserver((entries) => entries.forEach((entry) => handler(entry, observer)), options);
    elements.forEach((element) => observer.observe(element));
    disposers.push(() => observer.disconnect());
  };

  observe([...root.querySelectorAll("[data-reveal]")], (entry, observer) => {
    if (!entry.isIntersecting) return;
    entry.target.classList.add("is-visible");
    observer?.unobserve(entry.target);
  });
  observe([...root.querySelectorAll("[data-motion-scene]")], (entry) => entry.target.classList.toggle("is-in-view", entry.isIntersecting), { threshold: .2 });

  const formatCounter = (value, decimals) => Number(value).toLocaleString(state.language === "ar" ? "ar-SA" : "en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  const animateCounter = (element) => {
    const target = Number(element.dataset.countTarget || 0);
    const start = Number(element.dataset.countStart || target);
    const decimals = Number(element.dataset.countDecimals || 0);
    const prefix = element.dataset.countPrefix || "";
    const suffix = decimals ? "%" : "";
    if (reducedMotion) {
      element.textContent = `${prefix}${formatCounter(target, decimals)}${suffix}`;
      return;
    }
    const startedAt = performance.now();
    let frame = 0;
    const tick = (now) => {
      const progress = Math.min(1, (now - startedAt) / 1150);
      const eased = 1 - Math.pow(1 - progress, 3);
      element.textContent = `${prefix}${formatCounter(start + (target - start) * eased, decimals)}${suffix}`;
      element.classList.toggle("is-changing", progress < 1);
      if (progress < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    disposers.push(() => cancelAnimationFrame(frame));
  };
  observe([...root.querySelectorAll("[data-count-target]")], (entry, observer) => {
    if (!entry.isIntersecting || entry.target.dataset.counted === "true") return;
    entry.target.dataset.counted = "true";
    animateCounter(entry.target);
    observer?.unobserve(entry.target);
    const kind = entry.target.dataset.liveKind;
    if (!kind || reducedMotion) return;
    let value = Number(entry.target.dataset.countTarget || 0);
    const schedule = () => {
      const delay = kind === "customers" ? 45000 + Math.random() * 45000 : 14000 + Math.random() * 18000;
      const timer = setTimeout(() => {
        timers.delete(timer);
        if (!root.isConnected) return;
        value += kind === "customers" ? 1 + Math.floor(Math.random() * 2) : 1 + Math.floor(Math.random() * 5);
        entry.target.classList.add("is-changing");
        entry.target.textContent = formatCounter(value, 0);
        setTimeout(() => entry.target.classList.remove("is-changing"), 360);
        schedule();
      }, delay);
      timers.add(timer);
    };
    schedule();
  });

  const syncFeatureFlowGeometry = (network) => {
    const svg = network.querySelector("[data-flow-geometry]");
    const center = network.querySelector("[data-flow-center]");
    if (!svg || !center || getComputedStyle(svg).display === "none") return;
    const networkRect = network.getBoundingClientRect();
    const centerRect = center.getBoundingClientRect();
    if (!networkRect.width || !networkRect.height || !centerRect.width) return;
    const width = networkRect.width;
    const height = networkRect.height;
    const centerX = centerRect.left - networkRect.left + centerRect.width / 2;
    const centerY = centerRect.top - networkRect.top + centerRect.height / 2;
    const radius = Math.min(centerRect.width, centerRect.height) / 2;
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    network.querySelectorAll("[data-flow-line]").forEach((line) => {
      const node = network.querySelector(`[data-flow-node="${line.dataset.flowLine}"]`);
      if (!node) return;
      const nodeRect = node.getBoundingClientRect();
      const nodeCenterX = nodeRect.left - networkRect.left + nodeRect.width / 2;
      const cardY = nodeRect.top - networkRect.top + nodeRect.height / 2;
      const cardIsLeft = nodeCenterX < centerX;
      const cardX = cardIsLeft ? nodeRect.right - networkRect.left : nodeRect.left - networkRect.left;
      const direction = cardIsLeft ? 1 : -1;
      const terminalX = cardX + direction * 5;
      const normalizedY = Math.max(-1, Math.min(1, (cardY - centerY) / Math.max(1, height * .43)));
      const hubY = centerY + normalizedY * radius * .72;
      const hubYOffset = hubY - centerY;
      const hubXOffset = Math.sqrt(Math.max(0, radius * radius - hubYOffset * hubYOffset));
      const hubX = centerX + (cardIsLeft ? -hubXOffset : hubXOffset);
      const distance = Math.abs(hubX - terminalX);
      const controlOneX = terminalX + direction * distance * .38;
      const controlTwoX = hubX - direction * distance * .34;
      const path = `M ${terminalX} ${cardY} C ${controlOneX} ${cardY}, ${controlTwoX} ${hubY}, ${hubX} ${hubY}`;
      line.querySelectorAll("path").forEach((item) => item.setAttribute("d", path));
      const cardTerminal = line.querySelector(".flow-terminal-card");
      const centerTerminal = line.querySelector(".flow-terminal-center");
      cardTerminal?.setAttribute("cx", terminalX);
      cardTerminal?.setAttribute("cy", cardY);
      centerTerminal?.setAttribute("cx", hubX);
      centerTerminal?.setAttribute("cy", hubY);
    });
  };

  const syncHomeFlowGeometry = (network) => {
    const svg = network.querySelector("[data-home-flow-geometry]");
    const center = network.querySelector("[data-home-flow-center]");
    if (!svg || !center || getComputedStyle(svg).display === "none") return;
    const networkRect = network.getBoundingClientRect();
    const centerRect = center.getBoundingClientRect();
    if (!networkRect.width || !networkRect.height || !centerRect.width) return;
    const centerX = centerRect.left - networkRect.left + centerRect.width / 2;
    const centerY = centerRect.top - networkRect.top + centerRect.height / 2;
    const radius = Math.min(centerRect.width, centerRect.height) / 2;
    svg.setAttribute("viewBox", `0 0 ${networkRect.width} ${networkRect.height}`);
    const terminalOffset = 3.7;
    network.querySelectorAll("[data-home-flow-line]").forEach((line) => {
      const key = line.dataset.homeFlowLine;
      const node = network.querySelector(`[data-home-flow-node="${key}"]`);
      if (!node) return;
      const nodeRect = node.getBoundingClientRect();
      const nodeCenterX = nodeRect.left - networkRect.left + nodeRect.width / 2;
      const nodeCenterY = nodeRect.top - networkRect.top + nodeRect.height / 2;
      let terminalX = nodeCenterX;
      let terminalY = nodeCenterY;
      let vertical = false;
      if (key === "automation") {
        terminalY = nodeRect.bottom - networkRect.top + terminalOffset;
        vertical = true;
      } else if (key === "live" || (key === "success" && Math.abs(nodeCenterX - centerX) < nodeRect.width * .35)) {
        terminalY = nodeRect.top - networkRect.top - terminalOffset;
        vertical = true;
      } else if (nodeCenterX < centerX) {
        terminalX = nodeRect.right - networkRect.left + terminalOffset;
      } else {
        terminalX = nodeRect.left - networkRect.left - terminalOffset;
      }
      const deltaX = terminalX - centerX;
      const deltaY = terminalY - centerY;
      const length = Math.max(1, Math.hypot(deltaX, deltaY));
      const hubX = centerX + deltaX / length * radius;
      const hubY = centerY + deltaY / length * radius;
      const controlOneX = vertical ? terminalX : terminalX + (hubX - terminalX) * .4;
      const controlOneY = vertical ? terminalY + (hubY - terminalY) * .4 : terminalY;
      const controlTwoX = vertical ? hubX : hubX - (hubX - terminalX) * .28;
      const controlTwoY = vertical ? hubY - (hubY - terminalY) * .28 : hubY;
      const path = `M ${terminalX} ${terminalY} C ${controlOneX} ${controlOneY}, ${controlTwoX} ${controlTwoY}, ${hubX} ${hubY}`;
      line.querySelectorAll("path").forEach((item) => item.setAttribute("d", path));
      const cardTerminal = line.querySelector(".home-ops-terminal--card");
      const centerTerminal = line.querySelector(".home-ops-terminal--center");
      cardTerminal?.setAttribute("cx", terminalX);
      cardTerminal?.setAttribute("cy", terminalY);
      centerTerminal?.setAttribute("cx", hubX);
      centerTerminal?.setAttribute("cy", hubY);
    });
  };

  root.querySelectorAll(".home-ops-scene--hero").forEach((network) => {
    syncHomeFlowGeometry(network);
    network.classList.add("is-geometry-ready");
    const settleGeometry = () => requestAnimationFrame(() => syncHomeFlowGeometry(network));
    network.addEventListener("transitionend", settleGeometry);
    disposers.push(() => network.removeEventListener("transitionend", settleGeometry));
    if ("ResizeObserver" in window) {
      const resizeObserver = new ResizeObserver(() => requestAnimationFrame(() => syncHomeFlowGeometry(network)));
      resizeObserver.observe(network);
      disposers.push(() => resizeObserver.disconnect());
    }
  });

  root.querySelectorAll(".flow-network").forEach((network) => {
    syncFeatureFlowGeometry(network);
    if (network.matches(".flow-network-features") && "ResizeObserver" in window) {
      const resizeObserver = new ResizeObserver(() => requestAnimationFrame(() => syncFeatureFlowGeometry(network)));
      resizeObserver.observe(network);
      disposers.push(() => resizeObserver.disconnect());
    }
    const nodes = [...network.querySelectorAll("[data-flow-node]")];
    nodes.forEach((node) => {
      const enter = () => {
        network.classList.add("is-focused");
        const key = node.dataset.flowNode;
        network.querySelectorAll("[data-flow-node], [data-flow-line]").forEach((item) => item.classList.toggle("is-active", (item.dataset.flowNode || item.dataset.flowLine) === key));
      };
      const leave = () => {
        network.classList.remove("is-focused");
        network.querySelectorAll(".is-active").forEach((item) => item.classList.remove("is-active"));
      };
      node.addEventListener("mouseenter", enter);
      node.addEventListener("focusin", enter);
      node.addEventListener("mouseleave", leave);
      node.addEventListener("focusout", leave);
      disposers.push(() => { node.removeEventListener("mouseenter", enter); node.removeEventListener("focusin", enter); node.removeEventListener("mouseleave", leave); node.removeEventListener("focusout", leave); });
    });
  });

  observe([...root.querySelectorAll("[data-steps-scene]")], (entry) => {
    if (!entry.isIntersecting) return entry.target.classList.remove("is-running");
    entry.target.classList.add("is-running");
  }, { threshold: .35 });

  marketingMotionDisposer = () => {
    timers.forEach((timer) => clearTimeout(timer));
    disposers.forEach((dispose) => dispose());
  };
}

